INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_NOR_DVALINN_POETIC','ENT_NOR_DVALINN','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Sol among men ''tis called, but with the gods sunna, the dwarfs call it Dvalinn''s leika, the Jotuns eyglo, the Alfar fagrahvel, the Aesir''s sons alskir. _Vingthor_. 18. Tell me, Alvis, etc., how the clouds are called, which with showers are mingled in every world. _Alvis_. 19.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_AEGIR_POETIC','ENT_NOR_AEGIR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Aegir, who was well skilled in magic, once went to Asgard, where he met with a very good reception. Supper time being come, the twelve mighty Aesir,--Odin, Thor, Njord, Frey, Tyr, Heimdall, Bragi, Vidar, Vali, Ullur, Hoenir and Forseti, together with the Asynjor,--Frigga, Freyja, Gefjon, Iduna, Gerda, Siguna, Fulla and Nanna, seated themselves on their lofty doom seats, in a hall around which were ranged swords of such surpass','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_AESIR_POETIC','ENT_NOR_AESIR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Until there came three mighty and benevolent Aesir to the world from their assembly. They found on earth, nearly powerless, Ask and Embla, void of destiny. 18. Spirit they possessed not, sense they had not, blood nor motive powers, nor goodly colour. Spirit gave Odin, sense gave Hoenir, blood gave Lodur, and goodly colour. 19.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_ANDVARI_POETIC','ENT_NOR_ANDVARI','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','He informed Sigurd of his parentage, and how it befell that Odin, and Hoenir, and Loki came to Andvarafors (the waterfall of Andvari). In the fall there was an abundance of fish. There was a dwarf named Andvari, who had long lived in the fall in the likeness of a pike, and in which he supplied himself with food. "Our brother," continued Regin, "was named Otr, who often went into the fall in the likeness of an otter.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_BALDR_POETIC','ENT_NOR_BALDR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Together were the Aesir all in council, and the Asyniur all in conference, and they consulted, the mighty gods, why Baldr had oppressive dreams. 2. [To that god his slumber was most afflicting; his auspicious dreams seemed departed. They the Jötuns questioned, wise seers of the future, whether this might not forebode calamity? 3.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_BESTLA_POETIC','ENT_NOR_BESTLA','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Potent songs nine from the famed son I learned of Bolthorn, Bestla''s sire, and a draught obtained of the precious mead, drawn from Odhraerir. 143. Then I began to bear fruit, and to know many things, to grow and well thrive: word by word I sought out words, fact by fact I sought out facts. 144.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_DAGR_POETIC','ENT_NOR_DAGR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','She then espoused Delling, of the Aesir race, and their son was Day, (Dagr) a child light and beauteous like his father. Then took All-father, Night, and Day, her son, and gave them two horses and two cars, and set them up in the heavens that they might drive successively one after the other, each in twelve hours'' time, round the world.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_EINHERJAR_POETIC','ENT_NOR_EINHERJAR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','For their abode he has prepared Valhalla and Vingolf, where they are called Einherjar (Heroes or Champions). Odin is also called Hangagud, Haptagud, and Farmagud, and, besides these, was named in many ways when he went to King Geirraudr," forty-nine names in all.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_FENRIR_POETIC','ENT_NOR_FENRIR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Be silent, Ty! Thou couldst never settle a strife ''twixt two; of thy right hand also I must mention make, which Fenrir from thee tore. _Ty_. 39. I of a hand am wanting, but thou of honest fame; sad is the lack of either. Nor is the wolf at ease: he in bonds must bide, until the gods'' destruction. _Loki_. 40. Be silent, Ty; to thy wife it happened to have a son by me.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_FREKI_POETIC','ENT_NOR_FREKI','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Geri and Freki the war-wont sates, the triumphant sire of hosts; but on wine only the famed in arms, Odin, ever lives. 20. Hugin and Munin fly each day over the spacious earth. I fear for Hugin, that he come not back, yet more anxious am I for Munin. 21. Thund roars; joyful in Thiodvitnir''s water lives the fish; the rapid river seems too great for the battle-steed to ford. 22.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_FRIGG_POETIC','ENT_NOR_FRIGG','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Be thou silent, Frigg! Thou art Fiorgyn''s daughter, and ever hast been fond of men, since Ve and Vili, it is said, thou, Vidrir''s wife, didst both to thy bosom take. _Frigg_. 27. Know thou that if I had, in Oegir''s halls, a son like Baldr, out thou shouldst not go from the Aesir''s sons: thou should''st have been fiercely assailed. _Loki_. 28.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_GARM_POETIC','ENT_NOR_GARM','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Loud bays Garm before the Gnupa-cave, his bonds he rends asunder; and the wolf runs. 49. Hrym steers from the east, the waters rise, the mundane snake is coiled in jötun-rage. The worm beats the water, and the eagle screams: the pale of beak tears carcases; Naglfar is loosed. 50. That ship fares from the east: come will Muspell''s people o''er the sea, and Loki steers.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_GERI_POETIC','ENT_NOR_GERI','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Geri and Freki the war-wont sates, the triumphant sire of hosts; but on wine only the famed in arms, Odin, ever lives. 20. Hugin and Munin fly each day over the spacious earth. I fear for Hugin, that he come not back, yet more anxious am I for Munin. 21. Thund roars; joyful in Thiodvitnir''s water lives the fish; the rapid river seems too great for the battle-steed to ford. 22.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_GULLVEIG_POETIC','ENT_NOR_GULLVEIG','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','She that war remembers, the first on earth, when Gullveig they with lances pierced, and in the high one''s hall her burnt, thrice burnt, thrice brought her forth, oft not seldom; yet she still lives. 26. Heidi they called her, whithersoe''r she came, the well-foreseeing Vala: wolves she tamed, magic arts she knew, magic arts practised; ever was she the joy of evil people. 27.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_GUNNLOD_POETIC','ENT_NOR_GUNNLOD','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','With this bird''s pinions I was fettered in Gunnlods dwelling. 14. Drunk I was, I was over-drunk, at that cunning Fialar''s. It''s the best drunkenness, when every one after it regains his reason. 15. Taciturn and prudent, and in war daring, should a king''s children be; joyous and liberal every one should be until his hour of death. 16.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_HATI_POETIC','ENT_NOR_HATI','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Sköll the wolf is named, that the fair-faced goddess to the ocean chases; another Hati hight, he is Hrôdvitnir''s son; he the bright maid of heaven shall precede. 40. Of Ymir''s flesh was earth created, of his blood the sea, of his bones the hills, of his hair trees and plants, of his skull the heaven; 41. And of his brows the gentle powers formed Midgard for the sons of men; but of his brain the heavy clouds are all created.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_HYMIR_POETIC','ENT_NOR_HYMIR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Page Preface by the Translator ix Introduction to the Voluspa xv The Vala''s Prophecy 1 The Lay of Vafthrudnir 9 The Lay of Vegtam, or Baldur''s Dream 26 The High One''s Lay 29 Odin''s Rune Song 44 The Lay of Hymir 48 The Lay of Thrym, or the Hammer Recovered 53 The Lay of the Dwarf Alvis 57 The Lay of Harbard 63 The Journey, or Lay of Skirnir 71 The Lay of Rig 78 Egir''s Compotation, or Loki''s Altercation 84 The Lay of Fiolsvith 9','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_LOKI_POETIC','ENT_NOR_LOKI','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Having also seized Loki''s children, Vali and Nari, they changed the former into a wolf, and in this likeness he tore his brother to pieces and devoured him. The gods then made cords of his intestines, with which they bound Loki on the points of the rocks, one cord passing under his shoulders, another under his loins, and a third under his hams, and afterwards transformed these cords into thongs of iron.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_MIMIR_POETIC','ENT_NOR_MIMIR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','But under the root that stretches out towards the Frost-giants there is Mimir''s well, in which wisdom and wit lie hidden. The owner of this well is called Mimir. He is full of wisdom, because he drinks the waters of the well from the horn Gjoll every morning. One day All-father came and begged a draught of this water, which he obtained, but was obliged to leave one of his eyes as a pledge for it.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_MOTSOGNIR_POETIC','ENT_NOR_MOTSOGNIR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Then was Môtsognir created greatest of all the dwarfs, and Durin second; there in man''s likeness they created many dwarfs from earth, as Durin said. 11. Nýi and Nidi, Nordri and Sudri, Austri and Vestri, Althiôf, Dvalin Nâr and Nâin, Niping, Dain, Bivör, Bavör, Bömbur, Nori, An and Anar, Ai, Miodvitnir, 12. Veig and Gandâlf, Vindâlf, Thrain, Thekk and Thorin, Thrôr, Vitr, and Litr, Nûr and Nýrâd, Regin and Râdsvid.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_MUNDILFARI_POETIC','ENT_NOR_MUNDILFARI','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','"There was formerly a man," replied Har, "named Mundilfari, who had two children so lovely and graceful that he called the male, Mani (moon), and the female, Sol (sun), who espoused the man named Glenur.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_NJORD_POETIC','ENT_NOR_NJORD','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Yet Njord is not of the lineage of the Aesir, for he was born and bred in Vanaheim. But the Vanir gave him as hostage to the Aesir, receiving from them in his stead Hoenir. By this means was peace re-established between the Aesir and Vanir. Njord took to wife Skadi, the daughter of the giant Thjassi.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_NORNS_POETIC','ENT_NOR_NORNS','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','These maidens fix the lifetime of all men, and are called Norns. But there are, indeed, many other Norns, for, when a man is born, there is a Norn to determine his fate. Some are known to be of heavenly origin, but others belong to the races of the elves and dwarfs; as it is said-- "''Methinks the Norns were born far asunder, for they are not of the same race.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_MIMISBRUNNR_POETIC','ENT_NORR_MIMISBRUNNR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','The Deluding of Gylfi 256 Of the Primordial State of the Universe 259 Origin of the Frost-Giants 260 Of the Cow Audhumla, and Birth of Odin 262 The Making of Heaven and Earth 263 Creation of Man and Woman 265 Night and Day, Sun and Moon 266 Wolves that Pursue the Sun and Moon 267 The Way that Leads to Heaven 268 The Golden Age 269 Origin of the Dwarfs, and Norns of Destiny 270 The Ash Yggdrasill and Mimer''s Well 271 The Norns','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_NINE_WORLDS_POETIC','ENT_NORR_NINE_WORLDS','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Nine feet will go Fiörgyn''s son, bowed by the serpent, who feared no foe. All men will their homes forsake. 56. The sun darkens, earth in ocean sinks, fall from heaven the bright stars, fire''s breath assails the all-nourishing tree, towering fire plays against heaven itself. 57. She sees arise, a second time, earth from ocean, beauteously green, waterfalls descending; the eagle flying over, which in the fell captures fish.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_URDARBRUNNR_POETIC','ENT_NORR_URDARBRUNNR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','The Deluding of Gylfi 256 Of the Primordial State of the Universe 259 Origin of the Frost-Giants 260 Of the Cow Audhumla, and Birth of Odin 262 The Making of Heaven and Earth 263 Creation of Man and Woman 265 Night and Day, Sun and Moon 266 Wolves that Pursue the Sun and Moon 267 The Way that Leads to Heaven 268 The Golden Age 269 Origin of the Dwarfs, and Norns of Destiny 270 The Ash Yggdrasill and Mimer''s Well 271 The Norns','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NORR_VANAHEIM_POETIC','ENT_NORR_VANAHEIM','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','In Vanaheim wise powers him created, and to the gods a hostage gave. At the world''s dissolution, he will return to the wise Vanir. _Gagnrâd_. 40. Tell me eleventhly, since all the condition of the gods thou knowest, Vafthrûdnir! what the Einheriar do in Haerfather''s halls, until the powers perish? _Vafthrûdnir_. 41.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_SKIRNIR_POETIC','ENT_NOR_SKIRNIR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Page Preface by the Translator ix Introduction to the Voluspa xv The Vala''s Prophecy 1 The Lay of Vafthrudnir 9 The Lay of Vegtam, or Baldur''s Dream 26 The High One''s Lay 29 Odin''s Rune Song 44 The Lay of Hymir 48 The Lay of Thrym, or the Hammer Recovered 53 The Lay of the Dwarf Alvis 57 The Lay of Harbard 63 The Journey, or Lay of Skirnir 71 The Lay of Rig 78 Egir''s Compotation, or Loki''s Altercation 84 The Lay of Fiolsvith 9','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_SKULD_POETIC','ENT_NOR_SKULD','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Near the fountain, which is under the ash, stands a very beauteous dwelling, out of which go three maidens, named Urd, Verdandi, and Skuld. These maidens fix the lifetime of all men, and are called Norns. But there are, indeed, many other Norns, for, when a man is born, there is a Norn to determine his fate.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_THOR_POETIC','ENT_NOR_THOR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','My sire, fierce of mood, a kettle owns, a capacious cauldron, a rast in depth." _Thor_. 6. "Knowest thou whether we can get the liquor-boiler?" _Ty_. "Yes, friend! if we stratagem'' employ." Rapidly they drove forward that day from Asgard, till to the giant''s home they came. 7. Thor stalled his goats, splendid of horn, then turned him to the hall that Hymir owned.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_THRYM_POETIC','ENT_NOR_THRYM','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Hast thou Hlorridi''s hammer hidden?" _Thrym_. 9. "I have Hlorridi''s hammer hidden eight rasts beneath the earth; it shall no man get again, unless he bring me Freyia to wife." 10. Flew then Loki--the plumage rattled--until he came beyond the Jotun''s dwellings, and came within the Aesir''s courts; there he met Thor, in the middle court, who these words first of all uttered. 11.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_VANIR_POETIC','ENT_NOR_VANIR','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','By this means was peace re-established between the Aesir and Vanir. Njord took to wife Skadi, the daughter of the giant Thjassi. She preferred dwelling in the abode formerly belonging to her father, which is situated among rocky mountains, in the region called Thrymheim, but Njord loved to reside near the sea. They at last agreed that they should pass together nine nights in Thrymheim, and then three in Noatun.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_VERDANDI_POETIC','ENT_NOR_VERDANDI','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Near the fountain, which is under the ash, stands a very beauteous dwelling, out of which go three maidens, named Urd, Verdandi, and Skuld. These maidens fix the lifetime of all men, and are called Norns. But there are, indeed, many other Norns, for, when a man is born, there is a Norn to determine his fate.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_NOR_YGGDRASIL_POETIC','ENT_NOR_YGGDRASIL','SRC_POETIC_EDDA','The Poetic Edda','The Poetic Edda','Three roots stand on three ways under Yggdrasil''s ash: Hel under one abides, under the second the Hrimthursar, under the third mankind. 32. Ratatösk is the squirrel named, which, has to run in Yggdrasil''s ash; he from above the eagle''s words must carry, and beneath to Nidhögg repeat. 33. Harts there are also four, which from its summits, arch-necked, gnaw. Dâin and Dvalin, Duneyr and Durathrôr. 34.','Olive Bray',1908,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'English translation located by name within the work (not exact stanza); verify locus.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
